const D = { fr: obFr as Record<OKey, string>, en: obEn };
export type OT = (key: OKey, vars?: Record<string, string | number>) => string;

export function otranslate(lang: "fr" | "en", key: OKey, vars?: Record<string, string | number>): string {
  const s = D[lang][key] ?? obEn[key] ?? key;
  return vars ? s.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m)) : s;
}

export function useOT(): OT {
  const { lang } = useUI();
  return useCallback((key: OKey, vars?: Record<string, string | number>) => otranslate(lang, key, vars), [lang]);
}
